impl Solution {
    pub fn can_cross(a: Vec<u8>, m: usize, k: i64) -> bool {
        let n = a.len();
        let mut dp = vec![i64::MAX; n + 2];
        dp[0] = 0;

        for i in 1..=n + 1 {
            let start = if i > m { i - m } else { 0 };
            let end = i - 1;

            for j in start..=end {
                if dp[j] == i64::MAX {
                    continue;
                }

                let mut valid = false;
                let mut cost = 0;

                if j == 0 || j == n + 1 || (j >= 1 && j <= n && a[j - 1] == 2) {
                    if j + 1 <= i && i <= j + m {
                        valid = true;
                        cost = dp[j] + 0;
                    }
                } else if j >= 1 && j <= n && a[j - 1] == 0 {
                    if i == j + 1 {
                        valid = true;
                        cost = dp[j] + 1;
                    }
                }

                if valid && cost < dp[i] {
                    dp[i] = cost;
                }
            }
        }

        dp[n + 1] < i64::MAX && dp[n + 1] <= k
    }
}

